package com.example.employeeactivity; import android.content.Intent; import android.os.Bundle; import android.view.View; import android.widget.EditText; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { EditText etName,etId,etSalary; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);etName=findViewById(R.id.etName);etId=findViewById(R.id.etId);etSalary=findViewById(R.id.etSalary);} public void calculateSalary(View v){String name=etName.getText().toString().trim(),id=etId.getText().toString().trim(),s=etSalary.getText().toString().trim();if(name.isEmpty()||id.isEmpty()||s.isEmpty()){Toast.makeText(this,"Please fill all fields",Toast.LENGTH_SHORT).show();return;}double basic=Double.parseDouble(s),hra=basic*.20,da=basic*.10,gross=basic+hra+da;Intent i=new Intent(this,SecondaryActivity.class);i.putExtra("name",name);i.putExtra("id",id);i.putExtra("basic",basic);i.putExtra("hra",hra);i.putExtra("da",da);i.putExtra("gross",gross);startActivity(i);}}
